def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:

    if color and _platform_has_pgrp():
        pty, pid = _open_pty()
    else:
        pty, pid = None, None

    try:
        command = " ".join(cmd)
        command += " " + " ".join(varargs)
        if len(command) > _max_length:
            raise ValueError("Command is too long")

        # The actual command execution
        proc = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                              universal_newlines=True, **kwargs)
        output, error = proc.stdout, proc.stderr

        # Close pty
        if pty:
            os.close(pty)
        return proc.returncode, output

    # Close pty
    finally:
        if pty:
            os.close(pty)

