def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif value != d2[key] and not (isinstance(value, dict) and isinstance(d2[key], dict)):
            result[key] = value
        elif isinstance(value, dict) and isinstance(d2[key], dict):
            result[key] = difference(value, d2[key], level - 1)
    return result

def difference(d1, d2, level=-1):
    # Raise a ValueError if the inputs are not dictionaries
    if not (isinstance(d1, dict) and isinstance(d2, dict)):
        raise ValueError("Only dictionaries are supported as inputs.")

    # Set the level to -1 if not specified
    if level == -1:
        level = float("inf")  # Infinity

    # Handle the base case where the levels are equal to 0
    if level == 0:
        return d1

    # Initialize the difference dictionary
    diff = {}

    # Iterate over the items in d1 and compute the difference with d2
    for key, value in d1.items():
        # If the key is not present in d2, add it to the difference
        if key not in d2:
            diff[key] = value
        # If the key is present in d2, but the values are different, add it to the difference
        elif value != d2[key]:
            diff[key] = value

    # If the level is greater than 0, recurse over the subdictionaries
    if level > 0:
        # Iterate over the items in d1 and compute the difference with d2 for each subdictionary
        for key, value in diff.items():
            if isinstance(value, dict):
                subdiff = difference(value, d2[key], level-1)
                if subdiff:
                    diff[key] = subdiff
            elif isinstance(value, list):
                # TODO: Handle lists
                pass

    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

     *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    result = {}
    for key, value in d1.items():
        if not isinstance(value, dict) or level == 0:
            if value not in d2:
                result[key] = value
        else:
            difference_level = level - 1 if level > 0 else -1
            result_level = difference(value, d2.get(key, {}), difference_level)
            if result_level:
                result[key] = result_level
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from d1 not contained in d2.

    level sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in d1 and d2 but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    d1 and d2 remain unchanged. However, d1 or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument level.
    """
    result = {}
    for key, value in d1.items():
        if not d2.__contains__(key):
            result[key] = value
        elif level == 1:
            if value != d2[key]:
                result[key] = value
        elif level == 0:
            pass
        elif type(value) is dict:
            difference_ = difference(value, d2[key], level-1)
            if difference_:
                result[key] = difference_
        else:
            result[key] = value
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self._hist:
        i, j = self._get_bin_idx(coord)
        if i >= 0 and i < self.N and j >= 0 and j < self.N:
            self._hist[i, j] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if weight < 0:
        raise ValueError("weight must be non-negative")

    if coord < self.left or coord > self.right:
        return

    if self.fill_time_is_cumulative:
        self.data[coord] += weight
    else:
        self.data[coord] = weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.ndim:
        raise ValueError("Invalid coordinate, expected %d dimensions but got %d" % (self.ndim, len(coord)))

    if any(c < 0 or c >= self.shape[i] for i, c in enumerate(coord)):
        return

    self.count[self.__coord_to_index(coord)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    for key, value in labels.items():
        if not isinstance(key, str):
            raise ValidationError({key: "expected string or bytes-like object"})
        if not re.match(LABEL_KEY_REGEX, key):
            raise ValidationError({key: "Label key '{}' does not match the regex '{}'".format(key, LABEL_KEY_REGEX)})
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    raise ValidationError({key: "expected string or bytes-like object"})
                if not re.match(LABEL_VALUE_REGEX, item):
                    raise ValidationError({key: "Label value '{}' does not match the regex '{}'".format(item, LABEL_VALUE_REGEX)})
        elif not isinstance(value, str):
            raise ValidationError({key: "expected string or bytes-like object"})
        elif not re.match(LABEL_VALUE_REGEX, value):
            raise ValidationError({key: "Label value '{}' does not match the regex '{}'".format(value, LABEL_VALUE_REGEX)})

def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        try:
            key_matcher = re.match(r"^[A-Za-z0-9_]+$", key)
            if not key_matcher:
                errors.append({key: "Label key '%s' does not match the regex [...]" % key})
        except TypeError:
            errors.append({key: "expected string or bytes-like object"})
        if isinstance(value, list):
            for item in value:
                try:
                    value_matcher = re.match(r"^[A-Za-z0-9_]+$", item)
                    if not value_matcher:
                        errors.append({key: "Label value '%s' does not match the regex [...]" % item})
                except TypeError:
                    errors.append({key: "expected string or bytes-like object"})
    if errors:
        raise ValidationError("Validation failed", {"errors": errors})

