def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of the
	in-style parameters.

	:param sql: The SQL query.
	:type sql: str or bytes
	:param many_params: Contains each set of in-style parameters, which maps each parameter to a value.
	:type many_params: Mapping or Sequence
	:return: A tuple containing the formatted SQL query and a list of converted out-style parameters.
	:rtype: tuple(str or bytes, list(dict or list))
	"""

        # Validate input
        if not (isinstance(sql, str) or isinstance(sql, bytes)):
            raise TypeError("sql must be of type str or bytes")
        if not isinstance(many_params, Iterable):
            raise TypeError("many_params must be iterable")

        # Initialize output
        formatted_sql = []
        out_style_params = []

        # For each set of in-style parameters, convert to out-style parameters
        for params in many_params:
            if isinstance(self.in_style, str):
                # Named parameter style
                if not isinstance(params, Mapping):
                    raise TypeError("params must be a mapping")
                for name, value in params.items():
                    out_style_params.append({name: value})
            else:
                # Ordinal parameter style
                if not isinstance(params, Sequence):
                    raise TypeError("params must be a sequence")
                out_style_params.append(list(params))

        # Replace in-style parameters with out-style parameters in sql
        for param in out_style_params:
            if isinstance(param, Mapping):
                # Named parameter
                for name, value in param.items():
                    sql = sql.replace(":" + name, "?")
            else:
                # Ordinal parameter
                sql = sql.replace("?", str(param))

        # Append current parameter set to output
        formatted_sql.append(sql)
        out_style_params.append(param)

        return (formatted_sql, out_style_params)

