    for element in inventory:
        if element not in ["type", "date", "settings", "products"]:
            raise ValueError("Invalid inventory element")
        if element == "type":
            if inventory[element] not in [1, 2, 3]:
                raise ValueError("Unsupported specification version")
        elif element == "date":
            try:
                datetime.datetime.strptime(inventory[element], "%Y-%m-%d")
            except ValueError:
                raise ValueError("Invalid date format")
        elif element == "settings":
            if not isinstance(inventory[element], list):
                raise ValueError("Invalid settings type")
            for setting in inventory[element]:
                if not isinstance(setting, str):
                    raise ValueError("Invalid setting type")
                if setting not in ["T", "F", "O"]:
                    raise ValueError("Invalid setting")
        elif element == "products":
            if not isinstance(inventory[element], list):
                raise ValueError("Invalid products type")
            for product in inventory[element]:
                if not isinstance(product, dict):
                    raise ValueError("Invalid product type")
                for key in ["item_number", "containing_boxes"]:
                    if key not in product:
                        raise ValueError("Invalid product")
                if not isinstance(product["item_number"], str):
                    raise ValueError("Invalid item number type")
                if not isinstance(product["containing_boxes"], list):
                    raise ValueError("Invalid containing boxes type")
                for box in product["containing_boxes"]:
                    if not isinstance(box, str):
                        raise ValueError("Invalid box type")

    return True

