def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest in manifest_files:
        manifest_digests = set()
        for file in manifest.manifest_files:
            if file.digest in digests_used and file.digest not in manifest_digests:
                manifest_digests.add(file.digest)
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests missing from manifest: {', '.join(missing_digests)}")
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"Digests unused in manifest: {', '.join(unused_digests)}")

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("Input prior is not an InventoryValidator object")
        # Check that prior is an earlier version than current object
        if self.version == prior.version:
            raise ValueError("Input prior is the same version as current object")
        if self.version > prior.version:
            raise ValueError("Input prior is a later version than current object")
        # Check that prior's inventory contains all items and quantities in current inventory
        for item in self.items.values():
            if item not in prior.items:
                raise ValueError(f"Item {item.name} not found in prior inventory")
            elif prior.items[item] < item.quantity:
                raise ValueError(f"Insufficient quantity of item {item.name} in prior inventory")
        # Check that current inventory does not contain items not found in prior inventory
        for item in prior.items:
            if item not in self.items.keys():
                raise ValueError(f"Item {item.name} not found in current inventory")
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Input prior is not an InventoryValidator")

    if prior.version >= self.version:
        raise ValueError("Input prior is not a prior version of the current inventory object")

    for key, value in prior.inventory.items():
        if key not in self.inventory:
            raise ValueError(f"Key {key} missing from current inventory")
        if value != self.inventory[key]:
            raise ValueError(f"Value for key {key} does not match in prior inventory")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Expected InventoryValidator object for prior, but got {type(prior).__name__}")
    if prior.inventory is not self.inventory:
        raise ValueError("Inventory mismatch. The prior inventory is not from the same inventory as the current one")
    if prior.version >= self.version:
        raise ValueError(f"Prior inventory version {prior.version} is not less than the current version {self.version}")
    if len(self.objects) < len(prior.objects):
        raise ValueError(f"The current inventory has fewer objects ({len(self.objects)}) than the prior inventory ({len(prior.objects)})")
    # Check that prior is a subset of current
    for obj in prior.objects:
        if obj.id not in self._object_cache:
            raise ValueError(f"Object {obj.id} is in the prior inventory but not in the current inventory")
        prior_deps = set(obj.dependencies)
        current_deps = set(self._object_cache[obj.id].dependencies)
        if not prior_deps.issubset(current_deps):
            raise ValueError(f"Object {obj.id} has more dependencies in the prior inventory ({prior_deps}) than in the current inventory ({current_deps})")
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    map = {}
    for file in inventory.files:
        if file.version == version:
            map[file.logical_path] = set()
        elif file.logical_path in map:
            map[file.logical_path].add(file)
    return map

def get_logical_path_map(inventory, version):
