    for content_file in inventory.get_content_files(version):
        logical_path_in_state = content_file.logical_path_in_state
        if logical_path_in_state not in logical_path_map:
            logical_path_map[logical_path_in_state] = set()
        logical_path_map[logical_path_in_state].add(content_file)

    for dup_content_file in inventory.get_dup_content_files():
