            logical_path_in_state = dup_content_file.logical_path_in_state
            if logical_path_in_state not in logical_path_map:
                logical_path_map[logical_path_in_state] = set()
            logical_path_map[logical_path_in_state].add(dup_content_file.dup_content_state)

