def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    files_by_logical_path = {}
    for file in inventory:
        if file.version <= version:
            logical_path = file.logical_path
            if logical_path not in files_by_logical_path:
                files_by_logical_path[logical_path] = set()
            files_by_logical_path[logical_path].add(file)
    return files_by_logical_path

def get_logical_path_map(inventory, version):
    # Step 1: Collect all content files for the given version
    version_files = inventory.get_versioned_objects(version)
    content_files = [f for f in version_files if f.lower().endswith((".html", ".htm"))]

    # Step 2: Build a dictionary mapping logical paths to content files
    logical_path_map = {}
    for content_file in content_files:
        logical_path = content_file.get_logical_path()
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)

    # Step 3: Include references to duplicate files in later versions
    for logical_path in logical_path_map:
        for later_version in range(version + 1, inventory.get_latest_version() + 1):
            later_version_files = inventory.get_versioned_objects(later_version)
            for later_content_file in later_version_files:
                if later_content_file.get_logical_path() == logical_path:
                    logical_path_map[logical_path].add(later_content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    try:
        if not isinstance(fixity, dict):
            raise ValueError('Invalid fixity block: not a dictionary')
        for key, value in fixity.items():
            if key not in manifest_files:
                raise ValueError("Invalid file reference in fixity block: '%s' is not in the manifest" % key)
            if not isinstance(value, str):
                raise ValueError("Invalid fixity value for file '%s': not a string" % key)
            if value not in ('md5', 'sha1'):
                raise ValueError("Invalid fixity value for file '%s': '%s' is not a valid algorithm" % (key, value))
    except Exception as e:
        raise ValidationError("Invalid fixity block in inventory:\n%s" % str(e)) from e

def validate_fixity(self, fixity, manifest_files):
