    Check the structure of the fixity block and makes sure that only files listed in the manifest are referenced.
    """
    # Check if the fixity block is a dict
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dict")

    # Check if the fixity block has a 'files' key
    if 'files' not in fixity:
        raise ValueError("Fixity block does not have a 'files' key")

    # Check if the 'files' value is a list
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Fixity block 'files' value is not a list")

    # Check if all files in the fixity block are in the manifest
    for file in files:
        if file not in manifest_files:
            raise ValueError(f"File {file} in fixity block is not in the manifest")

    # Check if all files in the manifest are referenced in the fixity block
    for file in manifest_files:
        if file not in files:
