    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.

    Arguments:
        fixity (list): List of fixity information for the inventory.
        manifest_files (list): List of files included in the manifest.
    """
    # Check structure of fixity block
    if not isinstance(fixity, list):
        raise TypeError("Fixity block must be a list")
    if not fixity:
        raise ValueError("Fixity block must contain at least one fixity entry")

    for entry in fixity:
        if not isinstance(entry, dict):
            raise TypeError("Fixity entry must be a dictionary")
        if "filename" not in entry or not isinstance(entry["filename"], str):
            raise ValueError("Fixity entry must contain a filename string")
        if "hash" not in entry or not isinstance(entry["hash"], str):
            raise ValueError("Fixity entry must contain a hash string")

    # Check that all files referenced in fixity are in the manifest
    for entry in fixity:
        if not any(entry["filename"] == file_dict["filename"] for file_dict in manifest_files):
            raise ValueError(f"File {entry['filename']} referenced in fixity is not listed in the manifest")

    # Check that all files in the manifest have a fixity entry
    for file_dict in manifest_files:
        if not any(file_dict["filename"] == entry["filename"] for entry in fixity):
            raise ValueError(f"File {file_dict['filename']} listed in the manifest has no fixity information")

    # Returned parsed structure
    return {
        "fixity": fixity,
        "manifest_files": manifest_files
    }

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        return False

    if not isinstance(fixity, dict):
        raise TypeError("Fixity block is not a dictionary")

    if "files" not in fixity:
        raise ValueError("Fixity block does not contain a files section")

    files = fixity["files"]
    if not isinstance(files, list):
        raise TypeError("Files section is not a list")

    for file in files:
        if not isinstance(file, dict):
            raise TypeError("File is not a dictionary")

        if not "id" in file:
            raise ValueError("File does not contain a id")

        if not file["id"] in manifest_files:
            raise ValueError("File id " + file["id"] + " is not listed in the manifest")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check that all files referenced in the fixity block are present in the manifest
    for filepath, checksums in fixity.items():
        if filepath not in manifest_files:
            raise ValueError(f"File not found in manifest: {filepath}")

        # Check that the checksums are a list of strings
        if not isinstance(checksums, list):
            raise ValueError(f"Checksums for file {filepath} must be a list of strings")

        for checksum in checksums:
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum {checksum} for file {filepath} must be a string")

    # Check that all files in the manifest have a corresponding entry in the fixity block
    for filepath in manifest_files:
        if filepath not in fixity:
            raise ValueError(f"File not found in fixity block: {filepath}")

    return True

