def _explore_zipfile(zip_path):
    with ZipFile(zip_path, "r") as zipf:
        data = {}
        for info in zipf.infolist():
            name = Path(info.filename).stem
            if name not in data:
                data[name] = []
            data[name].append(zipf.read(info))
        return data

