def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:
        A & (A | B) = A, A | (A & B) = A

    Negative absorption:
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Expression):
            if arg.op == Operator.AND:
                if self.check_absorption(arg.op1, arg.op2):
                    new_args.append(arg.op1)
                else:
                    new_args.append(arg)
            elif arg.op == Operator.OR:
                if self.check_absorption(arg.op1, arg.op2):
                    new_args.append(arg.op2)
                else:
                    new_args.append(arg)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorb(arg1, arg2):
        if arg1 == "A" and arg2 == "A | B":
            return arg1
        elif arg1 == "A | B" and arg2 == "A":
            return arg2
        elif arg1 == "A" and arg2 == "~A | B":
            return arg1 + " & " + arg2
        elif arg1 == "A | B" and arg2 == "A":
            return arg1
        elif arg1 == "~A | B" and arg2 == "A":
            return arg1
        elif arg1 == "A & B" and arg2 == "A":
            return arg1
        elif arg1 == "A & B" and arg2 == "~A":
            return arg1
        elif arg1 == "A" and arg2 == "A & B":
            return arg2
        elif arg1 == "A" and arg2 == "~A & B":
            return arg1 + " | " + arg2
        elif arg1 == "A & B" and arg2 == "A | ~A":
            return arg1
        elif arg1 == "~A & B" and arg2 == "A | ~A":
            return arg1
        elif arg1 == "A | ~A" and arg2 == "A":
            return arg1
        elif arg1 == "A | ~A" and arg2 == "A | ~A":
            return arg1
        elif arg1 == "~A | B" and arg2 == "A":
            return arg1
        elif arg1 == "~A | B" and arg2 == "A | ~A":
            return arg1
        elif arg1 == "A & B" and arg2 == "A | ~A":
            return arg1
        elif arg1 == "~A & B" and arg2 == "A | ~A":
            return arg1
        else:
            return None

    result = []
    for arg in args:
        result.append(absorb(arg, args[0]))
    return result

def absorb(self, args):
    def distribute_A(A, B):
        """
        Distribute A to the left and right of | and &.

        >>> distribute_A('A', 'B & C')
        '(A & B) & (A & C)'
        >>> distribute_A('A', 'B | C')
        '(A | B) & (A | C)'
        """
        if '&' in B:
            return '(' + distribute_A(A, B.partition('&')[0]) + ' & ' + distribute_A(A, B.partition('&')[2]) + ')'
        elif '|' in B:
            return '(' + distribute_A(A, B.partition('|')[0]) + ' | ' + distribute_A(A, B.partition('|')[2]) + ')'
        else:
            return A + ' & ' + B

    def distribute_notA(A, B):
        """
        Distribute ~A to the left and right of | and &.

        >>> distribute_notA('A', 'B & C')
        '(~A & B) & (~A & C)'
        >>> distribute_notA('A', 'B | C')
        '(~A | B) & (~A | C)'
        """
        if '&' in B:
            return '(' + distribute_notA(A, B.partition('&')[0]) + ' & ' + distribute_notA(A, B.partition('&')[2]) + ')'
        elif '|' in B:
            return '(' + distribute_notA(A, B.partition('|')[0]) + ' | ' + distribute_notA(A, B.partition('|')[2]) + ')'
        else:
            return '~' + A + ' & ' + B

    def apply_absorption(expr):
        """
        Apply absorption on each node of the expression tree.
        """
        if expr.startswith('(') and expr.endswith(')'):
            node = expr[1:-1]
            if '&' in node and any(expr.isalpha() for expr in node.partition('&')[:2]):
                return apply_absorption(node.replace('&', '|', 1))
            elif '|' in node and any(expr.isalpha() for expr in node.partition('|')[:2]):
                return apply_absorption(node.replace('|', '&', 1))
            else:
                return '(' + apply_absorption(node.partition('&')[0]) + ' & ' + apply_absorption(node.partition('|')[2]) + ')'
        else:
            return expr

    def apply_negative_absorption(expr):
        """
        Apply negative absorption on each node of the expression tree.
        """
        if expr.startswith('(') and expr.endswith(')'):
            node = expr[1:-1]
            if '&' in node and any(expr.isalpha() for expr in node.partition('&')[:2]):
                return apply_negative_absorption(node.replace('&', '|', 1))
            elif '|' in node and any(expr.isalpha() for expr in node.partition('|')[:2]):
                return apply_negative_absorption(node.replace('|', '&', 1))
            else:
                return '(' + apply_negative_absorption(node.partition('&')[0]) + ' & ' + apply_negative_absorption(node.partition('|')[2]) + ')'
        else:
            return expr

    return list(sorted(set(
        map(apply_absorption, distribute_A(args[0], args[1])) +
        map(apply_negative_absorption, distribute_notA(args[0], args[1]))
    )))

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if isinstance(arg, Or):
            if any(isinstance(subarg, Not) and subarg.literal == arg.literals[0] for subarg in arg.literals):
                result.append(arg.literals[0])
            else:
                result.append(arg)
        elif isinstance(arg, And):
            if any(isinstance(subarg, Not) and subarg.literal == arg.literals[0] for subarg in arg.literals):
                result.append(arg.literals[1])
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

