def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not isinstance(namefunc, callable):
        raise TypeError("namefunc parameter must be a callable that takes one Unicode string argument and returns a Unicode string")

    if PY2:
        import datetime
        import codecs
        def wrapper(name):
            """Call encoded_namefunc with encoded parameter and decode the result."""
            if isinstance(name, bytes):
                # Conversion Unicode -> bytes is lossy, but there is no other way
                # to encode timezone names in Python 2
                bname = name. encode()
                return codecs. getencoder('UTF-8')(encoded_namefunc(bname), 'strict')
            else:
                return encoded_namefunc(name)
        return wrapper
    else:
        return namefunc

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        tzname_py3 = namefunc()
    except UnicodeEncodeError:
        pass
    else:
        return tzname_py3
    # In Python 2, try to return a byte string
    try:
        return tzname_py3.encode('ascii')
    except UnicodeEncodeError:
        raise ValueError("Cound not encode tzname_py3 as ascii")

def tzname_in_python2(namefunc):
