        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for child in self:
        if isinstance(child, StorageObject):
            num_objects += 1
            if validate_objects:
                try:
                    child.validate_object(check_digests)
                    good_objects += 1
                except ObjectInvalidError:
                    pass
            if show_warnings and not child.warnings:
                child.show_warnings()
    return num_objects, good_objects

