        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'other string' - some other directory type

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    matches = 0
    for filename in os.listdir(path):
        if filename.endswith(".txt"):
            matches += 1
        if matches >= 2:
            break

    if matches == 2:
        with open(os.path.join(path, "0=root.txt"), "r") as f:
            root_txt = f.read()
        if 'fcrepo.storage' in root_txt:
            return 'root'
        else:
            return 'other'
    elif matches == 1:
        with open(os.path.join(path, "0=object.txt"), "r") as f:
            object_txt = f.read()
        if 'fcrepo.object' in object_txt and 'fcrepo.version' in object_txt:
            return 'object'
        else:
            return 'other'
    else:
        return 'file'

