    if count_ocfl_root > 0 and count_ocfl_object == 0 and count_file == 0 and count_other == 0:
        return 'root'
    elif count_ocfl_root == 0 and count_ocfl_object > 0 and count_file == 0 and count_other == 0:
        return 'object'
    elif count_ocfl_root == 0 and count_ocfl_object == 0 and count_file > 0 and count_other == 0:
        return 'file'
    else:
        return f"error: cannot determine the type of {path}, found {count_ocfl_root} OCFL Storage Root, {count_ocfl_object} OCFL Object, {count_file} files, and {count_other} other files"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not isinstance(path, Path):
        path = Path(path)

    namastes = list(path.glob("0=*"))
    if not namastes:
        return "file"

    try:
        for namaste in namastes:
            with open(namaste, "r") as f:
                content = f.read()
                if "ocfl_object_root" in content:
                    return "root"
                elif "ocfl_object_id" in content:
                    return "object"
        return "file"
    except:
        return "file"

