def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key, value = node
        if isinstance(value, MappingNode):
            existing_node = next((n for n in result if n[0] == key), None)
            if existing_node:
                value = merge_nodes(value, existing_node[1], raise_on_collision=False)
            else:
                result.append(node)
        else:
