def deep_merge_nodes(nodes):
    # Create an empty dictionary to store the merged nodes
    merged_nodes = {}

    for node in nodes:
        # Get the key and value of the current node
        key = node[0]
        value = node[1]

        # If the key is already in the merged nodes, we need to deep merge the values
        if key in merged_nodes:
            # Get the existing value for the key
            existing_value = merged_nodes[key]

            # If the existing value is a MappingNode, we can deep merge the values
            if isinstance(existing_value, MappingNode):
                # Recursively deep merge the existing value and the new value
                merged_value = deep_merge_nodes(
                    [
                        (existing_value),
                        (value),
                    ]
                )

                # Update the merged nodes dictionary with the merged value
                merged_nodes[key] = merged_value
            else:
                # If the existing value is not a MappingNode, we simply take the new value
                merged_nodes[key] = value
        else:
            # If the key is not already in the merged nodes, we can simply add the node to the dictionary
            merged_nodes[key] = value

    return merged_nodes

