    for node in nodes:
        key, value = node
        for i, existing_node in enumerate(merged_nodes):
            existing_key, existing_value = existing_node
            if key == existing_key:
                if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                    merged_nodes[i] = (
                        key,
                        deep_merge_nodes([existing_value, value])
                    )
