def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex.
    polygon with vertices ABCD Will return DAB, ABC, BCD, CDA -> returns 3tuples
    #A    B    C    D -> of vertices"""

    points = []
    for i in range(len(vertices)):
        if i == 0:
            points.append((vertices[i], vertices[i + 1], vertices[i + 2]))
        elif i == len(vertices) - 1:
            points.append((vertices[i], vertices[i - 1], vertices[i + 1]))
        else:
            points.append((vertices[i], vertices[i - 1], vertices[i + 1]))
    return points

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or not alphabet:
        raise TypeError("alphabet must be a non-empty list")
    base = len(alphabet)
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("padding must be a non-negative integer")

    result = ""
    if number == 0:
        result = alphabet[0]
    else:
        while number > 0:
            result = alphabet[number % base] + result
            number //= base

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be a non-negative integer")
    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("alphabet must be a list of strings")
    if padding and not isinstance(padding, int):
        raise ValueError("padding must be a positive integer")
    if padding and padding < 0:
        raise ValueError("padding must be non-negative")

    result = []
    base = len(alphabet)
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])
    if padding:
        result.append("0" * padding)
    return "".join(reversed(result or ["0"]))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(symbol, str) for symbol in alphabet):
        raise TypeError("alphabet must contain only strings")
    if not all(len(symbol) == 1 for symbol in alphabet):
        raise ValueError("alphabet must contain only single-character strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer or None")

    # Convert the number to a list of integers, where each integer represents
    # the position of the corresponding symbol in the alphabet.
    number_list = []
    while number > 0:
        number_list.append(number % len(alphabet))
        number //= len(alphabet)

    # Convert the list of integers to a string, using the symbols from the alphabet.
    string = ""
    for index in range(len(number_list)):
        string += alphabet[number_list[index]]
        if padding is not None and len(string) < padding:
            string += "0" * (padding - len(string))

    return string

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer or None")
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must contain only strings")

    if number == 0:
        return alphabet[0]
    digits = []
    base = len(alphabet)
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base
    digits.reverse()
    if padding is not None:
        while len(digits) < padding:
            digits.append(alphabet[0])
    return "".join(digits)

