def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        pattern = r"'([^']*)'|"
        pattern += r'"([^"]*)"|'
        pattern += r'\s*((?:\\ |[^ ])+)\s*'
        pattern += r'|'
        pattern += r'\s+'
        regex = re.compile(pattern)
    elif platform == 'nt':
        pattern = r'(?:"([^"]*)"|'
        pattern += r"'([^']*)'|"
        pattern += r'((?:\\ |[^ ])+))'
        pattern += r'|'
        pattern += r'\s+'
        regex = re.compile(pattern)
    else:
        raise ValueError('invalid platform')

    tokens = []
    for match in regex.finditer(s):
        token = ''
        if match.group(1):
            token = match.group(1)
        elif match.group(2):
            token = match.group(2)
        elif match.group(3):
            token = match.group(3).replace('\\ ', ' ')

        if token:
            tokens.append(token)

    return tokens

