def make_find_paths(find_paths):
    new_find_paths = []
    for path in find_paths:
        if re.match(r'^pp:.+', path):
            new_find_paths.append(path)
        else:
            new_find_paths.append(f'sh:**/*{path}*/**')
    return new_find_paths

def make_find_paths(find_paths):
    """Transform all path fragments into glob patterns."""
    transformed_find_paths = []
    for find_path in find_paths:
        if re.match(r'\w+:\w+', find_path):
            # Pass through existing patterns untouched
            transformed_find_paths.append(find_path)
        else:
            # Transform path fragments into glob patterns
            transformed_find_paths.append(f'sh:**/*{find_path}*/**')
        return transformed_find_paths

