def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    #Type checking
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a list or tuple")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string")

    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary")

    #Format the command arguments
    cmd_args = []
    for command in commands:
        cmd_args.append(shlex.quote(command))

    for arg in args:
        cmd_args.append(shlex.quote(arg))

    command_line = " ".join(cmd_args)

    #Run the command
    if verbose:
        print("Running command:", command_line)

    process = subprocess.Popen(command_line, shell=True, cwd=cwd, env=env, stderr=None, stdout=None)
    process.wait()

    if process.returncode != 0:
        raise RuntimeError("Command returned non-zero exit code: %d" % process.returncode)

    return process.returncode

