def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.URIRef]] = None) -> Set[rdflib.URIRef]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    for triple in graph:
        if triple[1] == prop:
            roots.add(triple[0])

    # Keep adding nodes until no new roots are found
    found_new_roots = True
    while found_new_roots:
        found_new_roots = False
        for triple in graph:
            if triple[1] == prop and triple[0] not in roots:
                found_new_roots = True
                roots.add(triple[0])

    return roots

