    if isinstance(field_names, str):
        field_names = (field_names,)
    n = len(field_names)
    data = []
    if scale is None:
        scale = hist.scale
    for bin_ in hist:
        data.append((get_coordinate(bin_),) + make_value(bin_))
    return self.graph(scale, data, field_names)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    Args:
        hist: The histogram to convert.
        make_value: A function to set the value of a graph's point.
            By default, it is bin content.
        get_coordinate: Defines what the coordinate of a graph point
            created from a histogram bin will be.
            It can be "left" (default), "right" and "middle".
        field_names: Set field names of the graph. Their number
            must be the same as the dimension of the result.
        scale: Becomes the graph's scale (unknown by default).
            If it is ``True``, it uses the histogram scale.

    Returns:
        The graph converted from the histogram.
    """
    if make_value is None:
        def make_value(bin_):
            return bin_

    if get_coordinate == "left":
        def get_coordinate(bin_):
            return bin_.left
    elif get_coordinate == "right":
        def get_coordinate(bin_):
            return bin_.right
    elif get_coordinate == "middle":
        def get_coordinate(bin_):
            return bin_.middle
    else:
        raise ValueError("get_coordinate must be one of 'left', 'right', or 'middle'")

    if scale is None:
        scale = hist.scale
    elif scale is True:
        scale = hist.scale

    graph = Graph()
    for bin_ in hist.bins:
        x = get_coordinate(bin_)
        y = make_value(bin_)
        graph.add_point(x, y)

    return graph.set_scale(scale)

def verifyObject(iface, candidate, tentative=False):

    # Making sure the candidate claims that it provides the interface
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid('{} does not provide {}'.format(candidate, iface))

    # Making sure the candidate defines all the necessary methods
    for name, sig in iface.namesAndDescriptions(includeProvides=True):
        if name in ('__contains__', '__iter__'):
            # These methods are special-cased for registering utilities.
            # They are not needed for verifyObject.
            continue
        if not hasattr(candidate, name):
            raise zope.interface.Invalid('{} does not have attribute {}'.format(candidate, name))
        if sig is not None:
            try:
                getattr(candidate, name).getSignatureString()
            except AttributeError:
                raise zope.interface.Invalid('{} does not provide {}'.format(candidate, iface))

    # Making sure the candidate defines all the necessary attributes
    for name, value in iface.items():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid('{} does not have attribute {}'.format(candidate, name))
        if isinstance(value,zope.interface.Descriptor):
            try:
                # See zope.interface.declare.descriptor._checkUnrestricted
                value.getSignatureString()
            except AttributeError:
                raise zope.interface.Invalid('{} does not provide {}'.format(candidate, iface))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, type):
        raise ValueError("candidate must be a class, not an instance")

    if not iface:
        raise ValueError("iface must be a valid interface class")

    if iface not in inspect.getmro(candidate):
        if tentative:
            return False
        raise ValueError(f"{candidate.__name__} does not implement {iface.__name__}")

    for method in iface.__abstractmethods__:
        if method not in candidate.__dict__ or not callable(candidate.__dict__[method]):
            if tentative:
                return False
            raise ValueError(f"{candidate.__name__} does not implement {method}")
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        return False

    if tentative:
        for method in iface.abstractmethods():
            if not hasattr(candidate, method):
                return False
        return True
    else:
        for method in iface.__abstractmethods__:
            if not hasattr(candidate, method):
                return False
        return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check that the candidate is a class
    if not inspect.isclass(candidate):
        raise TypeError("Candidate must be a class.")

    # Check that the candidate has the necessary methods
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            raise TypeError("Candidate is missing method {}.".format(method))

    # Check that the candidate's methods have the correct signatures
    for method in iface.__abstractmethods__:
        if not verifySignature(getattr(iface, method), getattr(candidate, method)):
            raise TypeError("Candidate's method {} has an incorrect signature.".format(method))

    # If the candidate is not tentatively verified, check that it actually
    # implements all of the methods correctly
    if not tentative:
        if not issubclass(candidate, iface):
            raise TypeError("Candidate does not correctly implement the interface.")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate class implements the interface
    if not isinstance(candidate, iface):
        raise TypeError("Candidate class must implement the interface")

    # Check if the candidate class has all the methods and attributes defined in the interface
    for attr in iface.__attributes__:
        if not hasattr(candidate, attr):
            raise AttributeError(f"Candidate class does not have attribute { attr }")

        if not callable(getattr(candidate, attr)):
            raise TypeError(f"Attribute { attr } is not callable")

        if not isinstance(getattr(candidate, attr), iface.__attributes__[attr]):
            raise TypeError(f"Attribute { attr } is not of type { iface.__attributes__[attr] }")

    # Check if the candidate class has all the methods defined in the interface
    for method in iface.__methods__:
        if not hasattr(candidate, method):
            raise AttributeError(f"Candidate class does not have method { method }")

        if not callable(getattr(candidate, method)):
            raise TypeError(f"Method { method } is not callable")

        if not isinstance(getattr(candidate, method), iface.__methods__[method]):
            raise TypeError(f"Method { method } is not of type { iface.__methods__[method] }")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        if not tentative:
            raise NotImplementedError(f"{candidate} is not an instance of {iface}")
        return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Make a list of all metaclasses present in the base classes.
    metaclasses = []
    for base in bases:
        if hasattr(base, '__class__') and base.__class__ is not object:
            metaclasses.append(base.__class__)
    if explicit_mc is not None:
        metaclasses.append(explicit_mc)
    # Inherit from the metaclasses that are directly provided.
    if len(metaclasses) == 0:
        return object
    elif len(metaclasses) == 1:
        return metaclasses[0]
    else:
        return inheritMetaclasses(*metaclasses)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    elif len(bases) > 1:
        for mc in (type(base) for base in bases):
            if issubclass(mc, type):
                return mc
        return type
    elif bases:
        return type(bases[0])
    else:
        return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    else:
        # Determine the metaclass from the bases
        metaclass = type
        for base in bases:
            metaclass = type(base)
            # Metaclass conflict
            if metaclass is not type:
                return metaclass
        return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    if not bases:
        return type
    base_groups = {}
    for base in bases:
        group = base_groups.setdefault(type(base), [])
        group.append(base)
    for group in base_groups.values():
        for meta in group:
            if any(isinstance(x, meta) for x in group if x != meta):
                return meta
    return type

