def fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if not isinstance(dt, datetime.datetime):
            raise TypeError('dt must be a datetime.datetime object')

        if dt.tzinfo is None:
            raise ValueError('dt must be timezone-aware')

        self.tzinfo = dt.tzinfo
        self.datetime = dt.astimezone(self.tzinfo)

        # Check for ambiguous and fold states
        self.fold = _datetime_is_fold(self.datetime, self.tzinfo)
        self.ambiguous = _datetime_is_ambiguous(self.datetime, self.tzinfo)

    @staticmethod
    def _datetime_is_fold(dt, tz):
        # If the datetime is not datetime is not already fold, check if it is a
        # "fall-back" transition. If it is, then the datetime is fold.
        if not tz._is_fold(dt):
            for transition in tz._transitions:
                if transition[0] == dt.fold:
                    return True
        return False

    @staticmethod
    def _datetime_is_ambiguous(dt, tz):
        # If the datetime is not already ambiguous, check if it is a "spring-forward"
        # transition. If it is, then the datetime is ambiguous.
        if not tz._is_ambiguous(dt):
            for transition in tz._transitions:
                if transition[0] == dt.fold:
                    return True
        return False

