def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    text_list = text.split()
    for word in text_list:
        if word.startswith("<") and word.endswith(">"):
            tags.add(word)
            if replacer is not None:
                text_list[word] = replacer(word)
    return tags, " ".join(text_list)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Split the text into individual words
    words = text.split()

    # Iterate over each word
    for i, word in enumerate(words):
        # If the word is a link, add the "link" attribute
        if word.startswith("http") or word.startswith("www"):
            words[i] = word + '" link'

    # Join the words back into a string
    return " ".join(words)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    for link in text.links:
        if link.start_idx is None or link.end_idx is None:
            continue
        link_type = text.slice(link.start_idx, link.end_idx)
        if link_type.startswith('http'):
            link.type = 'HTTP'
        elif link_type.startswith('mailto'):
            link.type = 'EMAIL'
        else:
            link.type = 'TEXT'
        link.text = text.slice(link.start_idx, link.end_idx)
        text.attributes['processed_links'].append(link.to_dict())
    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    from bs4 import BeautifulSoup

    soup = BeautifulSoup(text, 'html.parser')
    links = soup.find_all('a')

    for link in links:
        if not link.get('link_type'):
            link['link_type'] = 'textual'
        if not link.get('target'):
            link['target'] = '_blank'
        if not link.get('rel'):
            link['rel'] = 'noreferrer'

    return soup.prettify()

