def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Validate the signature and public key
    try:
        signature_verifier.verify_signature(public_key, doc.content, signature)
    except Exception as e:
        raise InvalidSignatureError("Invalid signature") from e

    # Verify that the signature contains a validated id
    if not doc.verify_id(signature.id):
        raise InvalidSignatureError("Signature contains an invalidated id")

    # Verify that the signature is not expired
    if signature.expires and datetime.now() > signature.expires:
        raise InvalidSignatureError("Signature is expired")

    # Verify that the signature is not revoked
    if signature.revoked:
        raise InvalidSignatureError("Signature is revoked")

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        signed_element = doc.getElementsByTagName("signed")[0].
        element_to_verify = signed_element.getElementsByTagName("el")[0]
        digest_value = signed_element.getElementsByTagName("digestvalue")[0].
        digest_calculated = md5(str(element_to_verify.data).encode()).hexdigest()
        if digest_calculated != digest_value.data:
            return False
        else:
            return True
    except IndexError:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
      import json
      data = json.loads(document)
    except ValueError:
      from six import BytesIO
      from xmpp.utils.etree import tostring
      from xmpp.utils.webrss import RssParser
      rss_parser = RssParser(BytesIO(document))
      rss_tree = rss_parser.get_tree()
      data = rss_tree.getroot()

    aliases = []
    for item in data.findall(" XRD/Alias"):
      if item.text:
        aliases.append(item.text)

    profiles = []
    for item in data.findall(" XRD/Link"):
      if item.attrib["rel"] == "profile":
        profiles.append(item.attrib["href"])

    return {"aliases": aliases, "profiles": profiles}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if not isinstance(data, dict)) and not isinstance(data, list)))
            raise ValueError('Document is not a JSON object')

        if isinstance(data, dict)):
            return _parse_json_webfinger(data)
        else:
            return _parse_xrd_webfinger(data)
    except ValueError as e:
        raise ValueError('Invalid webfinger document') from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {"subject": data["subject"], "links": {link["rel"]: link["href"] for link in data["links"]}}
    except json.JSONDecodeError:
        pass
    try:
        root = etree.fromstring(document, parser=etree.XMLParser(huge_tree=True))
        nsmap = root.nsmap
        subject = root.find(".//XRD/Subject", nsmap).text
        links = root.findall(".//XRD/Link", nsmap)
        link_dict = {}
        for link in links:
            rel = link.attrib["rel"]
            href = link.attrib["href"]
            link_dict[rel] = href
        return {"subject": subject, "links": link_dict}
    except (etree.XMLSyntaxError, KeyError):
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        document = json.loads(document)
        return {
            "subject": document["subject"],
            "aliases": document["aliases"],
            "links": [{"rel": link["rel"], "type": link["type"], "href": link["href"]} for link in document["links"]],
        }
    except json.decoder.JSONDecodeError:
        document = etree.fromstring(document)
        xrd = {}
        for element in document.elements:
            if element.tag == "XRD":
                xrd["subject"] = element.attrib.get("subject")
                xrd["aliases"] = [alias.attrib.get("t") for alias in element.findall(".//xrd:Alias", namespaces=aliasNS)}
                xrd["links"] = [{"rel": link.attrib.get("rel"), "type": link.attrib.get("type"), "href": link.attrib.text} for link in element.findall(".//xrd:Link", namespaces=linkNS)}
                return xrd
    raise ValueError("Not a valid Diaspora webfinger document")

