def retrieve_diaspora_host_meta(host):
    import requests
    from lxml import etree

    host_meta_url = f"{host}/.well-known/host-meta.xrd"
    response = requests.get(host_meta_url)
    if response.status_code != 200:
        raise Exception(f"Failed to retrieve host-meta.xrd from {host}")

    host_meta = etree.fromstring(response.content)
    for xrd in host_meta.iter("XRD"):
        if xrd.get("type") == "http://docs.oasis-open.org/ns/xri/xrd-1.0":
            for link in xrd.iter("Link"):
                if link.get("rel") == "lrdd":
                    lrdd_url = link.get("template")
                    return lrdd_url

    raise Exception(f"Failed to find lrdd URL in host-meta.xrd for {host}")

