def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("First argument must be a dictionary")
    if not key:
        raise ValueError("At least one key must be provided")
    if keys:
        if not isinstance(keys, (tuple, list)):
            keys = [keys]
        keys.insert(0, key)
        for k in keys:
            if k not in dic:
                dic[k] = {}
            dic = dic[k]
        dic[key] = val
    else:
        dic[key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not isinstance(settings_dirs, list):
        raise TypeError("settings_dirs must be a list of SettingsDirectories")
    if spec_option not in {"FILE_NAMES", "FILES"}:
        raise ValueError("spec_option must be either 'FILE_NAMES' or 'FILES'")

    file_names = []
    for settings_dir in settings_dirs:
        if settings_dir.spec_option == spec_option:
            file_names.extend(settings_dir.file_names)

    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    from typing import List

    class IniType:
        """A complex type consisting of a list of file names"""

        def __init__(self, settings_dirs: List[str], spec_option: str):
            self.settings_dirs = settings_dirs
            self.spec_option = spec_option

        def generate_ini_file(self) -> List[str]:
            """Generate a list of INI file names based on the settings directories and spec option"""
            ini_file_names = []
            for settings_dir in self.settings_dirs:
                ini_file_names.append(f"{settings_dir}/{self.spec_option}.ini")
            return ini_file_names

