def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("No content provided")
    try:
        spec_data = yaml.safe_load(spec_content)
        if not spec_data:
            raise ValueError("No data loaded from spec file")
        # check for mandatory fields
        if not spec_data.get("name"):
            raise ValueError("No name field provided in spec file")
        if not spec_data.get("description"):
            raise ValueError("No description field provided in spec file")
        if not spec_data.get("entry"):
            raise ValueError("No entry field provided in spec file")
        if not spec_data.get("exit"):
            raise ValueError("No exit field provided in spec file")
    except (yaml.YAMLError, ValueError) as e:
        raise IRValidatorException("Error validating content: " + str(e))
    return spec_data

def validate_from_content(cls, spec_content=None):

    # check if the passed in content is None
    if spec_content is None:
        raise IRValidatorException("Spec content cannot be None")

    # check if the passed in content is an empty string
    if spec_content == "":
        raise IRValidatorException("Spec content cannot be empty")

    # attempt to load the content into a dictionary
    spec_dict = yaml.safe_load(spec_content)

    # check if the loaded dictionary is None
    if spec_dict is None:
        raise IRValidatorException("Spec content cannot be loaded into a dictionary")

    # check if the loaded dictionary is empty
    if not spec_dict:
        raise IRValidatorException("Spec content dictionary is empty")

    # check if the loaded dictionary has all the required fields
    required_fields = {"text", "main_image_url", "main_image_width", "main_image_height", "default_probability", "enabled"}
    if not all(field in spec_dict for field in required_fields):
        raise IRValidatorException("Spec content dictionary is missing one or more required fields")

    # check if the "text" field is a string
    if not isinstance(spec_dict["text"], str):
        raise IRValidatorException("\"text\" field must be a string")

    # check if the "main_image_url" field is a string
    if not isinstance(spec_dict["main_image_url"], str):
        raise IRValidatorException("\"main_image_url\" field must be a string")

    # check if the "main_image_width" field is an integer
    if not isinstance(spec_dict["main_image_width"], int):
        raise IRValidatorException("\"main_image_width\" field must be an integer")

    # check if the "main_image_height" field is an integer
    if not isinstance(spec_dict["main_image_height"], int):
        raise IRValidatorException("\"main_image_height\" field must be an integer")

    # check if the "default_probability" field is a float
    if not isinstance(spec_dict["default_probability"], float):
        raise IRValidatorException("\"default_probability\" field must be a float")

    # check if the "enabled" field is a boolean
    if not isinstance(spec_dict["enabled"], bool):
        raise IRValidatorException("\"enabled\" field must be a boolean")

    return spec_dict

