        parser_dict (dict): The dictionary containing the parsed data from the spec file.

    Raises:
        ValueError: If the required attributes are not present in the dictionary.
        KeyError: If any of the required attributes are not found in the dictionary.
        TypeError: If the type of any of the attributes is not as expected.
    """
    try:
        include_file = parser_dict['include']
    except KeyError:
        raise ValueError("The 'include' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'include' attribute must be a string.") from None
    if not isinstance(include_file, str) or not include_file:
        raise ValueError("The 'include' attribute must be a non-empty string.")

    try:
        include_groups = parser_dict['groups']
    except KeyError:
        raise ValueError("The 'groups' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'groups' attribute must be a list.") from None
    if not isinstance(include_groups, list) or not include_groups:
        raise ValueError("The 'groups' attribute must be a non-empty list.")

    try:
        included_names = parser_dict['names']
    except KeyError:
        raise ValueError("The 'names' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'names' attribute must be a list.") from None
    if not isinstance(included_names, list) or not included_names:
        raise ValueError("The 'names' attribute must be a non-empty list.")

    # Check if the include file exists
    filepath = os.path.join(os.path.dirname(__file__), include_file)
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file '{include_file}' does not exist.")

    # Read the include file
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()
        groups_dict = {}
        cur_group = None
        for line in lines:
            line = line.strip()
            # Skip empty lines and comments
            if not line or line.startswith('#'):
                continue
            # Check if we have a new group
            if line.startswith('['):
                cur_group = line[1:-1].strip()
                if cur_group not in include_groups:
                    raise ValueError(f"The specified group '{cur_group}' is not valid.")
                groups_dict[cur_group] = []
            # Add the line to the current group
            else:
                if cur_group is None:
                    raise ValueError("A value is specified outside of a group.")
                groups_dict[cur_group].append(line)

    # Filter the groups based on the names provided
    filtered_groups = {}
    for group, lines in groups_dict.items():
        if len(lines) == 1:
            filtered_groups[group] = lines[0]
    if len(filtered_groups) == 0:
        raise ValueError("No group was specified in the include file.")

    # Remove the include and groups attributes
    parser_dict.pop('include')
    parser_dict.pop('groups')

    # Add the filtered groups to the dictionary
    parser_dict.update(filtered_groups)

    return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

        for group_name, group_members in parser_dict.items():
            for member in group_members:
                if member not in self.groups[group_name]:
                    self.groups[group_name].append(member)
        for group_name, group_members in self.groups.items():
            for member in group_members:
                if member not in self.members:
                    self.members.append(member)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.
    """
    included_groups = set()
    for key, value in parser_dict.items():
        if key == "include":
            included_groups.update(value)
    return list(included_groups)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Check if the value is a dict with a 'groups' key
    if not isinstance(parser_dict, dict) or 'groups' not in parser_dict:
        return parser_dict
    # Extract the groups names
    groups = parser_dict['groups']
    # Remove the 'groups' key from the dict
    parser_dict = {k: v for k, v in parser_dict.items() if k != 'groups'}
    # Iterate over the group names and include the corresponding groups in the dict
    for group in groups:
        included_group = getattr(self, group)
        if included_group is None:
            continue
        for key, value in included_group.items():
            parser_dict.setdefault(key, []).extend(value)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    include_groups = parser_dict.setdefault('groups', {})
    for group_name, group_def in include_groups.items():
        group_members = group_def.get('members', [])
        group_regex = group_def.get('regex', None)
        if group_regex:
            try:
                group_regex = re.compile(group_regex)
            except re.error as e:
                raise ValueError(f'Invalid regex for group {group_name}: {e}')
        else:
            group_regex = re.compile('\*')

        group_members = list(set(self.pygmentize) - set(group_members))
        for line in include_groups.get('lines', []):
            for group_member in group_members:
                if group_regex.search(line):
                    group_def['members'].append(group_member)
                    break

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    resolved_args = {}

    for arg_name in self.arguments:
        if arg_name in self.spec.arguments:
            resolved_args[arg_name] = self.spec.arguments[arg_name]
        else:
            resolved_args[arg_name] = getattr(self.parent, arg_name)

    return resolved_args

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    for spec in self.specs:
        if spec.default is not None:
            if isinstance(spec.default, Value):
                value = spec.default.value
            else:
                value = spec.default
        else:
            value = self.get_value(spec.name)

        if value is not None:
            self.resolve(spec.name, value)
        else:
            self.resolve_description(spec.name)

    return None

