def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    conditionally_required_args = []
    for option in options_spec:
        if option['required_when'] is not None:
            condition_met = False
            for when in option['required_when']:
                if when['command'] == command_name and when['options'] <= args:
                    condition_met = True
                    break
            if condition_met:
                conditionally_required_args.append(option['name'])
    return conditionally_required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []
    for opt in options_spec:
        if opt.required_when:
            predicate = opt.required_when
            if isinstance(predicate, func_spec):
                predicate = partial(predicate, self.request)
            if predicate(command_name, args):
                required_args.append(opt.name)
    return required_args

