        """
        if extra_vars is not None:
            for k, v in extra_vars.items():
                vars_dict[k] = v

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is not None:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = None

    return vars_dict

def merge_extra_vars(cls, vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        for name, value in extra_vars.items():
            if name in vars_dict and vars_dict[name] != value:
                raise ValueError("extra-var '{}' is already defined with value '{}'".format(name, vars_dict[name]))
            vars_dict[name] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    if not playbook_path or not ir_workspace.is_file(playbook_path):
        raise FileNotFoundError("The specified playbook file does not exist")
    if not isinstance(verbose, int):
        raise ValueError("The 'verbose' parameter must be an integer")
    if extra_vars and not isinstance(extra_vars, dict):
        raise ValueError("The 'extra_vars' parameter must be a dictionary")
    if ansible_args and not isinstance(ansible_args, dict):
        raise ValueError("The 'ansible_args' parameter must be a dictionary")

    cmd = ['ansible-playbook']
    if verbose:
        cmd.extend(['-v', str(verbose)])
    if extra_vars:
        for key, value in extra_vars.items():
            cmd.extend(['-e', '{}={}'.format(key, value)])
    if ansible_args:
        for key, value in ansible_args.items():
            cmd.extend([key, str(value)])
    cmd.append(playbook_path)

    print('Running Ansible playbook: {}'.format(' '.join(cmd)))
    ir_plugin.run_cmd(cmd)

