def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        for argument, value in values_dict.items():
            if value == 'True':
                values_dict[argument] = True
            elif value == 'False':
                values_dict[argument] = False
            elif value == 'None':
                values_dict[argument] = None
            elif value.isdigit():
                values_dict[argument] = int(value)
            elif value.replace('.', '', 1).isdigit():
                values_dict[argument] = float(value)
        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        if "value" in values_dict:
            try:
                values_dict["value"] = int(values_dict["value"])
            except ValueError:
                pass
        if "action" in values_dict and values_dict["action"] == "store":
            values_dict["nargs"] = 1
        if "choices" in values_dict and values_dict["choices"] == "store_true":
            values_dict["nargs"] = 0
    elif parser_name == "virsh":
        if "value" in values_dict:
            try:
                values_dict["value"] = float(values_dict["value"])
            except ValueError:
                pass
        if "action" in values_dict and values_dict["action"] == "store_true":
            values_dict["nargs"] = 0
    elif parser_name == "ospd":
        if "value" in values_dict:
            try:
                values_dict["value"] = bool(values_dict["value"])
            except ValueError:
                pass
        if "action" in values_dict and values_dict["action"] == "store":
            values_dict["nargs"] = 1
    else:
        raise ValueError("Unsupported parser name")
    return values_dict

