def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    Arguments:
        plugin_dir {str} -- A path to the plugin's dir

    Returns:
        dict -- A flatten dictionary contains the plugin's properties
    """

    plugin_spec = load_yaml_file(os.path.join(plugin_dir, 'plugin.spec.yaml'))
    if plugin_spec is None:
        raise ValueError('No plugin.spec.yaml found in {}'.format(plugin_dir))

    flat_dict = {}

    for prop, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_prop, sub_value in value.items():
                flat_dict[sub_prop] = sub_value
        else:
            flat_dict[prop] = value

    return flat_dict

