def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    spec_parser = root_subparsers.add_parser("spec", help="Generate an OpenAPI specification file for the given application.")

    spec_parser.add_argument("--spec-file", required=False, default=None, help="The output file for the specification.")
    spec_parser.add_argument("--spec-format", required=False, default="yaml", choices=["yaml", "json"], help="The output file format for the specification. Defaults to yaml.")

    spec_parser.set_defaults(func=self.generate_spec)


    def generate_spec(spec_file=None, spec_format="yaml"):
        spec = generate_spec_dict(self.app)

        if spec_file is None:
            print(yaml.dump(spec))
        else:
            with open(spec_file, "w", encoding="utf-8") as f:
                if spec_format == "yaml":
                    yaml.dump(spec, f)
                else:
                    json.dump(spec, f)

    return generate_spec

